    7.1.0

     Support pour offsets négatifs a été ajouté.

  &reftitle.examples;

   mb_strpos retourne un décalage en caractères, pas en octets


<?php
// "🐘" fait 4 octets mais 1 caractère ; "é" fait 2 octets mais 1 caractère
$str = "🐘H🐘é";

var_dump(mb_strpos($str, "é"));  // caractère 3, pas octet 9
var_dump(mb_strpos($str, "🐘", 1)); // caractère 2, en sautant le premier "🐘"
?>


   &example.outputs;


int(3)
int(2)
